(()=>{const q=s=>document.querySelector(s),confirm=q('#confirm'),animation=q('#animation');let pending=null,busy=false,timer;
function card(h,result,state){const el=document.createElement('article');el.className='card '+h.rarity;el.innerHTML=(h.portrait?`<img src="${h.portrait}" alt="${h.name}">`:`<div class="symbol" aria-hidden="true">${h.role==='劍士'?'⚔':h.role==='弓箭手'?'➶':'✧'}</div>`)+`<small>${h.rarity} · ${h.role}</small><strong>${h.name}</strong>`;const p=document.createElement('p');p.textContent=result?(result.isNew?'NEW · 永久解鎖':'重複角色 · 專屬突破印記＋1'):(state.owned[h.id]?`已持有 · 印記 ${state.owned[h.id]-1}`:'尚未取得');el.append(p);return el}
function render(){const s=Summon.load(localStorage);const o=Summon.onboarding(s);q('#tutorial-link').hidden=!o.intro||o.complete;q('#tutorial-link').href=o.first?'portrait.html?tutorial=1':'tutorial.html';q('#tutorial-link').textContent=o.first?'下一步：編隊與戰鬥教學（完成領1,000鑽）':'先完成介紹，領取首抽100鑽';q('#balance').textContent=`鑽石 ${s.diamonds}`;q('#progress').textContent=`SSR保底 ${s.pity} / 50 · 召喚點數 ${s.points} / 120`;q('#single').disabled=busy||s.diamonds<100;q('#ten').disabled=busy||s.diamonds<1000;q('#pool').replaceChildren(...Summon.pool.map(h=>card(h,null,s)));q('#results').replaceChildren(...s.last.map(r=>card(Summon.pool.find(h=>h.id===r.id),r,s)));q('#exchange').replaceChildren(...Summon.pool.filter(h=>h.rarity==='SSR').map(h=>{const b=document.createElement('button');b.textContent=h.name+' · 120點';b.disabled=busy||s.points<120;b.onclick=()=>ask({id:h.id},`使用120點兌換${h.name}？`);return b}))}
function ask(action,text){pending=action;q('#confirm-text').textContent=text;confirm.showModal()}
function stop(){clearTimeout(timer);if(animation.open)animation.close()}
q('#skip').onclick=stop;animation.addEventListener('cancel',()=>clearTimeout(timer));q('#cancel').onclick=()=>confirm.close();q('#single').onclick=()=>ask({count:1},'消耗100鑽石，召喚1位角色？');q('#ten').onclick=()=>ask({count:10},'消耗1,000鑽石，召喚10位角色？');
q('#accept').onclick=async()=>{if(busy)return;const action=pending;confirm.close();busy=true;try{render();if(!navigator.locks)throw Error('請使用支援安全存檔的新版本瀏覽器');const s=await navigator.locks.request(Summon.key,()=>action.id?Summon.exchange(localStorage,action.id):Summon.draw(localStorage,action.count));render();const rarity=s.last.some(r=>Summon.pool.find(h=>h.id===r.id).rarity==='SSR')?'SSR':s.last.some(r=>Summon.pool.find(h=>h.id===r.id).rarity==='SR')?'SR':'R';animation.dataset.rarity=rarity;q('#glow').textContent=rarity+' · 星門開啟';animation.showModal();timer=setTimeout(stop,matchMedia('(prefers-reduced-motion: reduce)').matches?300:2200);q('#notice').textContent='結果已保存。'}catch(e){q('#notice').textContent='未完成操作：'+e.message}finally{busy=false;try{render()}catch{}}};
async function init(){try{if(!navigator.locks)throw Error('請使用支援安全存檔的新版本瀏覽器');await navigator.locks.request(Summon.key,()=>Onboarding.migrate(localStorage));await navigator.locks.request(Summon.key,()=>Summon.rewards(localStorage,Starboard.load(localStorage).firstClears));render()}catch(e){q('#notice').textContent=e.message;q('#single').disabled=q('#ten').disabled=true}}init();window.addEventListener('storage',()=>{try{render()}catch(e){q('#notice').textContent=e.message;q('#single').disabled=q('#ten').disabled=true}});
})();
